package com.tripcraft.controller;

import com.fasterxml.jackson.databind.ObjectMapper; import com.tripcraft.security.JwtService; import com.tripcraft.service.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;

@RestController @RequestMapping("/api")
public class ApiController {
  private final JdbcTemplate db; private final PasswordEncoder encoder; private final JwtService jwt; private final BookingService bookingService; private final InvoiceService invoiceService; private final AiService aiService; private final ObjectMapper mapper;
  public ApiController(JdbcTemplate db,PasswordEncoder encoder,JwtService jwt,BookingService bookingService,InvoiceService invoiceService,AiService aiService,ObjectMapper mapper){this.db=db;this.encoder=encoder;this.jwt=jwt;this.bookingService=bookingService;this.invoiceService=invoiceService;this.aiService=aiService;this.mapper=mapper;}
  @GetMapping("/health") public Map<String,String> health(){db.queryForObject("SELECT 1",Integer.class);return Map.of("status","UP","service","tripcraft-api");}
  record Register(@Email String email,@Size(min=6) String password,@NotBlank String fullName,String phone,List<String> interests){} record Login(@Email String email,@NotBlank String password){}
  @PostMapping("/auth/register") public ResponseEntity<?> register(@Valid @RequestBody Register x){
    String email=x.email().trim().toLowerCase(Locale.ROOT);
    db.update("INSERT INTO users(email,password_hash,full_name,phone) VALUES(?,?,?,?)",email,encoder.encode(x.password()),x.fullName(),x.phone());
    long id=db.queryForObject("SELECT id FROM users WHERE email=?",Long.class,email);
    if(x.interests()!=null) for(String interest:x.interests()) db.update("INSERT IGNORE INTO user_interests(user_id,interest) VALUES(?,?)",id,interest.toUpperCase(Locale.ROOT));
    String role="ROLE_TOURIST";
    return ResponseEntity.status(201).body(Map.of("user",withoutPassword(user(email)),"accessToken",jwt.issue(email,role)));
  }
  @PostMapping("/auth/login") public Map<String,Object> login(@Valid @RequestBody Login x){
    String email=x.email().trim().toLowerCase(Locale.ROOT);
    Map<String,Object> u;
    try {
      u=user(email);
    } catch(org.springframework.dao.EmptyResultDataAccessException e) {
      throw new IllegalArgumentException("Invalid email or password");
    }
    if(!isActive(u.get("active"))||!encoder.matches(x.password(),(String)u.get("passwordHash")))
      throw new IllegalArgumentException("Invalid email or password");
    return Map.of("user",withoutPassword(u),"accessToken",jwt.issue(email,(String)u.get("role")));
  }
  @PostMapping("/auth/logout") public ResponseEntity<Void> logout(){return ResponseEntity.noContent().build();}
  @GetMapping("/users/me") public Map<String,Object> me(org.springframework.security.core.Authentication a){return withoutPassword(user(a.getName()));}
  @PutMapping("/users/me") public Map<String,Object> update(org.springframework.security.core.Authentication a,@RequestBody Map<String,Object> b){db.update("UPDATE users SET full_name=?,phone=? WHERE email=?",b.get("fullName"),b.get("phone"),a.getName());if(b.get("interests") instanceof List<?> interests){long uid=db.queryForObject("SELECT id FROM users WHERE email=?",Long.class,a.getName());db.update("DELETE FROM user_interests WHERE user_id=?",uid);for(Object interest:interests)db.update("INSERT IGNORE INTO user_interests(user_id,interest) VALUES(?,?)",uid,String.valueOf(interest).toUpperCase(Locale.ROOT));}return me(a);}
  @GetMapping("/destinations") public Map<String,Object> destinations(@RequestParam(required=false) String search){String q=search==null?"%":"%"+search+"%"; return Map.of("content",db.queryForList("SELECT id,name,slug,state,description,best_season,hero_image_url heroImageUrl FROM destinations WHERE active=1 AND name LIKE ? ORDER BY name",q),"totalElements",db.queryForObject("SELECT COUNT(*) FROM destinations WHERE active=1 AND name LIKE ?",Integer.class,q));}
  @GetMapping("/destinations/{id}") public Map<String,Object> destination(@PathVariable long id){Map<String,Object>d=db.queryForMap("SELECT * FROM destinations WHERE id=?",id);d.put("places",db.queryForList("SELECT id,name,description,difficulty,price,duration_minutes durationMinutes,rating,image_url imageUrl FROM places WHERE destination_id=? AND active=1 ORDER BY rating DESC",id));d.put("hotels",db.queryForList("SELECT id,name,star_rating starRating,address,image_url imageUrl FROM hotels WHERE destination_id=? AND active=1",id));return d;}
  @GetMapping("/packages") public Map<String,Object> packages(@RequestParam(required=false) Long destinationId,@RequestParam(required=false) String search,@RequestParam(required=false) BigDecimal minPrice,@RequestParam(required=false) BigDecimal maxPrice,@RequestParam(required=false) Integer duration,@RequestParam(required=false) String date){StringBuilder sql=new StringBuilder("SELECT p.*,d.name destinationName FROM packages p JOIN destinations d ON d.id=p.destination_id WHERE p.active=1");List<Object> args=new ArrayList<>();if(destinationId!=null){sql.append(" AND p.destination_id=?");args.add(destinationId);}if(search!=null&&!search.isBlank()){sql.append(" AND (p.title LIKE ? OR d.name LIKE ?)");args.add("%"+search+"%");args.add("%"+search+"%");}if(minPrice!=null){sql.append(" AND p.price_per_person>=?");args.add(minPrice);}if(maxPrice!=null){sql.append(" AND p.price_per_person<=?");args.add(maxPrice);}if(duration!=null){sql.append(" AND p.duration_days=?");args.add(duration);}if(date!=null&&!date.isBlank()){sql.append(" AND EXISTS (SELECT 1 FROM package_dates pd WHERE pd.package_id=p.id AND pd.travel_date=? AND pd.seats_booked<pd.seats_total)");args.add(LocalDate.parse(date));}sql.append(" ORDER BY p.id DESC");List<Map<String,Object>> rows=db.queryForList(sql.toString(),args.toArray());return Map.of("content",rows,"totalElements",rows.size());}
  @GetMapping("/packages/{id}") public Map<String,Object> pack(@PathVariable long id){Map<String,Object> p=db.queryForMap("SELECT p.*,d.name destinationName,h.name hotelName FROM packages p JOIN destinations d ON d.id=p.destination_id LEFT JOIN hotels h ON h.id=p.hotel_id WHERE p.id=?",id); p.put("places",db.queryForList("SELECT pp.*,pl.name,pl.description,pl.price,pl.duration_minutes durationMinutes,pl.image_url imageUrl FROM package_places pp JOIN places pl ON pl.id=pp.place_id WHERE pp.package_id=? ORDER BY pp.day_number,pp.order_no",id)); return p;}
  @GetMapping("/packages/{id}/places") public List<Map<String,Object>> packPlaces(@PathVariable long id){return db.queryForList("SELECT pp.*,pl.name,pl.price,pl.duration_minutes durationMinutes FROM package_places pp JOIN places pl ON pl.id=pp.place_id WHERE pp.package_id=? ORDER BY pp.day_number,pp.order_no",id);}
  @GetMapping("/packages/{id}/reviews") public List<Map<String,Object>> packageReviews(@PathVariable long id){return db.queryForList("SELECT r.rating,r.review_text reviewText,u.full_name author,r.created_at createdAt FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.package_id=? ORDER BY r.created_at DESC",id);}
  @PostMapping("/bookings") public ResponseEntity<?> draft(@RequestBody Map<String,Object> b,org.springframework.security.core.Authentication a){
    if(b.get("packageId")==null) throw new IllegalArgumentException("Package ID is required");
    long packageId=Long.parseLong(String.valueOf(b.get("packageId")));
    Integer count=db.queryForObject("SELECT COUNT(*) FROM packages WHERE id=? AND active=1",Integer.class,packageId);
    if(count==null||count==0) throw new java.util.NoSuchElementException("Package not found");
    long userId=db.queryForObject("SELECT id FROM users WHERE email=?",Long.class,a.getName());
    List<Long> existing=db.queryForList("SELECT id FROM bookings WHERE user_id=? AND package_id=? AND status='DRAFT' ORDER BY id DESC LIMIT 1",Long.class,userId,packageId);
    if(!existing.isEmpty()){ return ResponseEntity.ok(bookingService.booking(existing.get(0))); }
    db.update("INSERT INTO bookings(booking_code,user_id,package_id) VALUES(UUID(),?,?)",userId,packageId);
    long bookingId=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);
    db.update("INSERT INTO booking_places(booking_id,place_id,day_number,order_no,price) SELECT ?,place_id,day_number,order_no,0 FROM package_places WHERE package_id=? AND type='MANDATORY'",bookingId,packageId);
    return ResponseEntity.status(201).body(bookingService.booking(bookingId));
  }
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @PutMapping("/bookings/{id}/details") public Map<String,Object> details(@PathVariable long id,@RequestBody Map<String,Object> b){return bookingService.saveDetails(id,b);}
  @GetMapping("/bookings") public List<Map<String,Object>> bookings(org.springframework.security.core.Authentication a){return db.queryForList("SELECT b.*,p.title,d.name destinationName FROM bookings b JOIN users u ON u.id=b.user_id JOIN packages p ON p.id=b.package_id JOIN destinations d ON d.id=p.destination_id WHERE u.email=? ORDER BY b.created_at DESC",a.getName());}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @GetMapping("/bookings/{id}") public Map<String,Object> booking(@PathVariable long id){return bookingService.booking(id);}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @PostMapping("/bookings/{id}/price-preview") public Map<String,Object> preview(@PathVariable long id){return bookingService.pricePreview(id);}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @PostMapping("/bookings/{id}/extend-day") public Map<String,Object> extendDay(@PathVariable long id){return bookingService.extendDay(id);}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @PostMapping("/bookings/{id}/places") public Map<String,Object> addPlace(@PathVariable long id,@RequestBody Map<String,Object> x){return bookingService.addPlace(id,Long.parseLong(String.valueOf(x.get("placeId"))),intValue(x.getOrDefault("dayNumber",1)),intValue(x.getOrDefault("orderNo",1)));}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @DeleteMapping("/bookings/{id}/places/{placeId}") public Map<String,Object> removePlace(@PathVariable long id,@PathVariable long placeId){return bookingService.removePlace(id,placeId);}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @PutMapping("/bookings/{id}/places/reorder") public Map<String,Object> reorderPlaces(@PathVariable long id,@RequestBody Map<String,Object> x){return bookingService.reorderPlaces(id,(List<Map<String,Object>>)x.getOrDefault("places",List.of()));}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @PostMapping("/bookings/{id}/rooms") public Map<String,Object> addRooms(@PathVariable long id,@RequestBody Map<String,Object> x){return bookingService.saveRooms(id,(List<Map<String,Object>>)x.getOrDefault("rooms",List.of()));}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @PostMapping("/bookings/{id}/vehicles") public Map<String,Object> addVehicles(@PathVariable long id,@RequestBody Map<String,Object> x){return bookingService.saveVehicles(id,(List<Map<String,Object>>)x.getOrDefault("vehicles",List.of()));}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @PutMapping("/bookings/{id}/travelers") public Map<String,Object> travelers(@PathVariable long id,@RequestBody Map<String,Object> x){return bookingService.saveTravelers(id,(List<Map<String,Object>>)x.getOrDefault("travelers",List.of()));}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @GetMapping(value="/bookings/{id}/invoice",produces=MediaType.APPLICATION_PDF_VALUE) public ResponseEntity<byte[]> invoice(@PathVariable long id){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=tripcraft-"+id+".pdf").body(invoiceService.generate(id));}
  @PostMapping("/packages/{id}/reviews") public ResponseEntity<?> review(@PathVariable long id,@RequestBody Map<String,Object> x,org.springframework.security.core.Authentication a){
    int rating=intValue(x.get("rating")); String text=String.valueOf(x.getOrDefault("reviewText",""));
    if(rating<1||rating>5||text.isBlank()||text.length()>2000)throw new IllegalArgumentException("Rating must be 1-5 and review text is required");
    Map<String,Object> booking=db.queryForMap("SELECT b.id,b.travel_date,b.status,u.id user_id FROM bookings b JOIN users u ON u.id=b.user_id WHERE b.id=? AND b.package_id=? AND u.email=?",x.get("bookingId"),id,a.getName());
    Object dateObj=booking.get("travel_date");
    LocalDate travelDate=dateObj instanceof java.sql.Date d?d.toLocalDate():dateObj instanceof LocalDate ld?ld:dateObj!=null?LocalDate.parse(String.valueOf(dateObj).substring(0,10)):null;
    if(!"CONFIRMED".equals(booking.get("status"))||travelDate==null||!travelDate.isBefore(LocalDate.now()))
      throw new IllegalStateException("Reviews are available after a completed trip");
    db.update("INSERT INTO reviews(user_id,package_id,booking_id,rating,review_text) VALUES(?,?,?,?,?)",booking.get("user_id"),id,booking.get("id"),rating,text);
    return ResponseEntity.status(201).body(Map.of("packageId",id,"rating",rating,"reviewText",text,"author",a.getName()));
  }
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @PostMapping("/bookings/{id}/pay") public Map<String,Object> pay(@PathVariable long id){return bookingService.confirmAndPay(id);}
  @PreAuthorize("@bookingSecurity.isOwner(#id, authentication.name)") @PostMapping("/bookings/{id}/cancel") public Map<String,Object> cancel(@PathVariable long id){return bookingService.cancel(id);}
  @GetMapping("/hotels/{id}/rooms") public List<Map<String,Object>> rooms(@PathVariable long id,@RequestParam String checkin,@RequestParam String checkout){return db.queryForList("SELECT rm.*,rm.total_units-COALESCE((SELECT SUM(br.quantity) FROM booking_rooms br JOIN bookings b ON b.id=br.booking_id WHERE br.room_id=rm.id AND b.status='CONFIRMED' AND b.travel_date BETWEEN ? AND ?),0) availableUnits FROM rooms rm WHERE rm.hotel_id=? AND rm.active=1",LocalDate.parse(checkin),LocalDate.parse(checkout),id);}
  @GetMapping("/vehicles") public List<Map<String,Object>> vehicles(@RequestParam long destinationId,@RequestParam(required=false) String date,@RequestParam(required=false) Integer seats){String seatClause=seats==null?"":" AND v.seat_capacity>=?";if(date==null||date.isBlank()){return seats==null?db.queryForList("SELECT v.*,v.units_available availableUnits FROM vehicles v JOIN destination_vehicles dv ON dv.vehicle_id=v.id WHERE dv.destination_id=? AND v.active=1",destinationId):db.queryForList("SELECT v.*,v.units_available availableUnits FROM vehicles v JOIN destination_vehicles dv ON dv.vehicle_id=v.id WHERE dv.destination_id=? AND v.active=1 AND v.seat_capacity>=?",destinationId,seats);}String sql="SELECT v.*,GREATEST(0,v.units_available-COALESCE((SELECT SUM(bv.quantity) FROM booking_vehicles bv JOIN bookings b ON b.id=bv.booking_id WHERE bv.vehicle_id=v.id AND b.status='CONFIRMED' AND b.travel_date=?),0)) availableUnits FROM vehicles v JOIN destination_vehicles dv ON dv.vehicle_id=v.id WHERE dv.destination_id=? AND v.active=1"+seatClause+" HAVING availableUnits>0";return seats==null?db.queryForList(sql,date, destinationId):db.queryForList(sql,date,destinationId,seats);}
  @PreAuthorize("@bookingSecurity.isOwner(#bookingId, authentication.name)") @GetMapping("/ai/recommendations") public Map<String,Object> recommendations(@RequestParam long bookingId){return Map.of("provider","rule-based","recommendations",db.queryForList("SELECT pl.id,pl.name,pl.price,pl.duration_minutes durationMinutes,pl.rating,CASE WHEN EXISTS (SELECT 1 FROM place_tags pt2 JOIN user_interests ui2 ON UPPER(ui2.interest)=UPPER(pt2.tag) WHERE pt2.place_id=pl.id AND ui2.user_id=b.user_id) THEN 'Matches your interests' ELSE 'Fits the destination and remaining trip time' END reason FROM places pl JOIN bookings b ON b.id=? JOIN packages p ON p.id=b.package_id WHERE pl.destination_id=p.destination_id AND NOT EXISTS (SELECT 1 FROM booking_places bp WHERE bp.booking_id=b.id AND bp.place_id=pl.id) AND pl.duration_minutes<=GREATEST(60,p.duration_days*360-COALESCE((SELECT SUM(pl2.duration_minutes) FROM booking_places bp2 JOIN places pl2 ON pl2.id=bp2.place_id WHERE bp2.booking_id=b.id),0)) AND NOT (pl.difficulty='HARD' AND EXISTS (SELECT 1 FROM booking_travelers bt WHERE bt.booking_id=b.id AND (bt.age<13 OR bt.age>65))) ORDER BY CASE WHEN EXISTS (SELECT 1 FROM place_tags pt3 JOIN user_interests ui3 ON UPPER(ui3.interest)=UPPER(pt3.tag) WHERE pt3.place_id=pl.id AND ui3.user_id=b.user_id) THEN 0 ELSE 1 END,pl.rating DESC,pl.price LIMIT 5",bookingId));}
  @PostMapping("/ai/budget-plan") public Map<String,Object> plan(@RequestBody Map<String,Object> body, org.springframework.security.core.Authentication a){
    Long userId=null;
    if(a!=null&&a.isAuthenticated()&&!"anonymousUser".equals(a.getName())){
      try{ userId=db.queryForObject("SELECT id FROM users WHERE email=?",Long.class,a.getName()); }catch(Exception ignored){}
    }
    return aiService.budget(body,userId);
  }
  @PostMapping("/ai/budget-plan/{planId}/book") public ResponseEntity<?> bookPlan(@PathVariable long planId,@RequestBody Map<String,Object> b,org.springframework.security.core.Authentication a){return draft(Map.of("packageId",planId),a);}
  @PostMapping("/ai/log-click") public ResponseEntity<Void> logAiClick(@RequestBody Map<String,Object> body,org.springframework.security.core.Authentication a){Long userId=db.queryForObject("SELECT id FROM users WHERE email=?",Long.class,a.getName());try{db.update("INSERT INTO ai_logs(user_id,endpoint,request_summary,provider,success) VALUES(?,?,?,?,?)",userId,"ai-plan-click",mapper.writeValueAsString(body),"client",true);}catch(Exception ignored){}return ResponseEntity.noContent().build();}
  @PreAuthorize("hasRole('ADMIN')") @GetMapping("/admin/stats") public Map<String,Object> stats(){return Map.of("bookings",db.queryForObject("SELECT COUNT(*) FROM bookings",Integer.class),"revenue",db.queryForObject("SELECT COALESCE(SUM(total_amount),0) FROM bookings WHERE status='CONFIRMED'",BigDecimal.class),"popularDestinations",db.queryForList("SELECT d.name,COUNT(*) bookings FROM bookings b JOIN packages p ON p.id=b.package_id JOIN destinations d ON d.id=p.destination_id GROUP BY d.id ORDER BY bookings DESC LIMIT 5"));}
  @PreAuthorize("hasRole('ADMIN')") @GetMapping("/admin/ai/status") public Map<String,Object> aiStatus(){
    return Map.of("configured",aiService.configured(),"model",aiService.getModel()!=null&&!aiService.getModel().isBlank()?aiService.getModel():"fallback");
  }
  @PreAuthorize("hasRole('ADMIN')") @PostMapping("/admin/ai/test") public Map<String,Object> aiTest(){return Map.of("success",aiService.configured(),"message",aiService.configured()?"LLM configuration is present":"LLM key is missing; rule-based fallback is active","latencyMs",0);}
  private boolean isActive(Object value){if(value instanceof Boolean b)return b;if(value instanceof Number n)return n.intValue()!=0;return "1".equals(String.valueOf(value))||"true".equalsIgnoreCase(String.valueOf(value));} private int intValue(Object x){return x==null?0:((Number)x).intValue();} private Map<String,Object> user(String email){Map<String,Object> u=db.queryForMap("SELECT id,email,password_hash passwordHash,full_name fullName,phone,role,active FROM users WHERE email=?",email);u.put("interests",db.queryForList("SELECT interest FROM user_interests WHERE user_id=? ORDER BY interest",u.get("id")).stream().map(x->x.get("interest")).toList());return u;} private Map<String,Object> withoutPassword(Map<String,Object> u){Map<String,Object>x=new LinkedHashMap<>(u);x.remove("passwordHash");return x;}
}
